function heading(title,subtitle='',actions='',concept=false){return '<div class="page-heading"><div><h1>'+title+(concept?' <span class="badge concept">扩展概念</span>':'')+'</h1><div class="subtitle">'+subtitle+'</div></div><div class="heading-actions">'+actions+'</div></div>'}
function card(label,value,unit='',body=''){return '<div class="panel"><div class="label">'+label+'</div><div class="stat-value">'+value+' <small>'+unit+'</small></div>'+body+'</div>'}
function icon(symbol){return '<div class="tiny-icon">'+symbol+'</div>'}
function toggle(key,checked){return '<label class="toggle"><input type="checkbox" aria-label="'+key+'" '+(checked?'checked':'')+' onchange="setSetting(\''+key+'\',this.checked)"><span class="switch"></span></label>'}
function empty(title,detail,button=''){return '<div class="panel empty-state"><div class="symbol">◇</div><h3>'+title+'</h3><p>'+detail+'</p>'+button+'</div>'}
function route(page){if(!pageNames[page])page='clean';location.hash=page;if(state.page===page)render();}
function render(){state.page=pageNames[location.hash.slice(1)]?location.hash.slice(1):'clean';$('mainNav').innerHTML=mainPages.map(p=>'<button data-page="'+p+'" class="'+(state.page===p?'active':'')+'">'+({ai:'AI',disk:'分析',maintenance:'维护'}[p]||pageNames[p])+'</button>').join('');document.querySelectorAll('.rail button').forEach(b=>b.classList.toggle('active',b.dataset.page===(state.page==='run'?'plans':state.page)));$('main').innerHTML=({home:homePage,clean:cleanPage,ai:aiPage,apps:appsPage,disk:diskPage,maintenance:maintenancePage,status:statusPage,plans:plansPage,activity:activityPage,recovery:recoveryPage,settings:settingsPage,run:runPage}[state.page])();updateSelectionBar();updateTaskChip();document.title='CleanManager · '+pageNames[state.page];}
window.addEventListener('hashchange',()=>{closeDrawer();$('contextMenu').hidden=true;render()});
document.addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b){e.preventDefault();route(b.dataset.page)}if(!e.target.closest('#contextMenu'))$('contextMenu').hidden=true;});
function homePage(){return heading('空间与日常','本机演示快照 · 今天 10:24','<button onclick="chooseScope()">选择范围</button><button class="primary" onclick="route(\'clean\')">查看清理</button>')+'<div class="three-col">'+card('卷空闲观测','82.0','GiB','<div class="bar"><span style="width:68%"></span></div><p class="muted">256 GiB 总容量 · 当前系统盘</p>')+card('已知逻辑量','94.0','GiB','<p class="muted">用户目录 · 2 个范围未读取</p>')+card('可审阅演示缓存',size(candidates.filter(eligible).reduce((n,c)=>n+c.amount,0)),'','<p class="muted">保护项与共享数据不计入候选</p>')+'</div><div class="three-col section-gap">'+feature('▧','空间去哪了','目录表与色块联动','磁盘分析','disk')+feature('✧','AI 与开发工具','缓存、会话与模型各有边界','查看数据','ai')+feature('↶','需要找回文件','查看隔离记录与恢复条件','打开恢复','recovery')+'</div><div class="two-col section-gap"><div class="panel"><h2>最近活动</h2>'+state.history.slice(0,3).map(h=>'<div class="row"><div class="row-main"><div class="row-name">'+h.title+'</div><div class="row-meta">'+h.time+'</div></div><button class="ghost" onclick="route(\'activity\')">'+h.status+' ›</button></div>').join('')+'</div><div class="panel"><h2>待查看</h2><div class="row">'+icon('!')+'<div class="row-main"><div class="row-name">1 个中断操作需要核对</div><div class="row-meta">先查明对象状态，再处理后续动作</div></div><button onclick="reconcile(\'h2\')">核对</button></div><div class="row">'+icon('↶')+'<div class="row-main"><div class="row-name">'+state.recovery.length+' 项隔离内容</div><div class="row-meta">30 天后提醒 · 不自动清空</div></div><button onclick="route(\'recovery\')">查看</button></div></div></div>'}
function feature(symbol,title,detail,action,page){return '<button class="feature-card" data-page="'+page+'"><div class="symbol">'+symbol+'</div><h3>'+title+'</h3><p>'+detail+'</p><div class="foot"><span>'+action+'</span><span>→</span></div></button>'}
function cleanPage(){const running=['running','stopping'].includes(state.scan);const title=heading('清理','范围内扫描 · 逐项审阅','<button class="scope-button" onclick="chooseScope()">▱ '+esc(state.scanRoot)+' ▾</button>');if(state.scan==='idle'||running){return title+'<div class="scan-hero"><div class="scan-art '+(running?'running':'')+'"><div class="scan-orbit"></div><div class="scan-ring"></div><div class="scan-disc"></div><div class="scan-center"><div class="number">'+(running?['4,210','12,680','18,420'][state.scanPhase]:'82.0')+(running?'':' <small>GiB</small>')+'</div><div class="label">'+(running?'已发现条目':'卷空闲观测')+'</div></div></div><div class="hero-copy"><h2>'+(state.scan==='stopping'?'正在停止':running?'看清空间的来处':'留出空间，也保留重要内容')+'</h2><p>'+(running?'只读发现与索引 · 总量尚未知':'先扫描你选择的范围，再查看每项的来源与影响')+'</p>'+(running?'<div class="inline-actions"><button class="primary" onclick="viewPartial()">查看已有结果</button><button '+(state.scan==='stopping'?'disabled':'')+' onclick="cancelScan()">取消扫描</button></div>':'<button class="primary" onclick="startScan()">开始只读扫描 →</button>')+'<div class="hero-facts"><div><b>'+(running?['8.1','19.4','24.6'][state.scanPhase]+' GiB':'不下载')+'</b><span>'+(running?'已确认逻辑量':'云占位内容')+'</span></div><div><b>'+(running?'00:0'+(state.scanPhase+1):'只读')+'</b><span>'+(running?'演示计时':'链接与挂载边界保留')+'</span></div></div></div></div><div class="three-col">'+feature('◇','应用缓存','看清归属与再生成影响','查看应用','apps')+feature('✧','AI 与开发工具','会话、工作树与模型默认保留','查看分类','ai')+feature('▧','大文件分析','体积大，不代表可以删除','浏览磁盘','disk')+'</div>'}return title+'<div class="notice '+(state.scan==='cancelled'?'warn':'')+'"><span>'+(state.scan==='cancelled'?'扫描已取消 · 已确认结果保留':'部分范围已读取 · 2 个位置未读取')+'</span><button onclick="scanGaps()">查看缺口 ›</button></div><div class="controls"><div class="chips">'+[['all','全部'],['apps','应用缓存'],['dev','开发工具'],['ai','AI 缓存'],['system','临时文件'],['protected','受保护']].map(([id,n])=>'<button class="'+(state.cleanGroup===id?'active':'')+'" onclick="state.cleanGroup=\''+id+'\';render()">'+n+'</button>').join('')+'</div><button class="ghost" onclick="startScan()">重新扫描 ↻</button></div><div class="split"><section class="panel"><div class="row" style="padding-top:0"><h2 style="margin:0">候选内容</h2><button class="ghost" onclick="selectVisibleCandidates()">选择当前可审阅项</button></div>'+candidates.filter(c=>state.cleanGroup==='all'||c.group===state.cleanGroup).map(candidateRow).join('')+'</section><aside class="panel"><h2>先看影响</h2><div class="row"><span class="muted">可重建</span><span>明确规则与归属</span></div><div class="row"><span class="muted">用户成果</span><span>默认保留</span></div><div class="row"><span class="muted">未知 / 在用</span><span>保持未选</span></div><div class="notice">选择不会修改文件</div><button style="width:100%" onclick="route(\'recovery\')">查看隔离与恢复 ↗</button></aside></div>'}
function candidateRow(c){const allowed=eligible(c),status=state.removed.has(c.id)?'已隔离':candidateProtected(c)?'自定义保护':c.eligible?'演示规则':c.group==='protected'?'受保护':'在用 · 保留';return '<div class="check-row"><input type="checkbox" aria-label="选择 '+c.name+'" data-candidate="'+c.id+'" '+(state.selected.has(c.id)&&allowed?'checked':'')+' '+(!allowed?'disabled':'')+' onchange="selectCandidate(\''+c.id+'\',this.checked)"><div class="row-main"><div class="row-name">'+c.name+'</div><div class="row-meta">'+c.owner+' · '+c.impact+'</div></div><span class="pill '+(allowed?'good':'')+'">'+status+'</span><span class="row-size">'+size(c.amount)+'</span><button class="ghost" onclick="candidateDetail(\''+c.id+'\')" aria-label="'+c.name+' 详情">›</button></div>'}
function startScan(){if(['running','stopping'].includes(state.scan))return toast('扫描正在进行');clearInterval(state.scanTimer);state.scan='running';state.scanPhase=0;route('clean');render();state.scanTimer=setInterval(()=>{if(state.scan!=='running'){clearInterval(state.scanTimer);return}state.scanPhase++;if(state.scanPhase>2){clearInterval(state.scanTimer);state.scan='partial';toast('演示扫描结束 · 可查看已知结果');}if(state.page==='clean')render();else updateTaskChip()},900)}
function cancelScan(){if(state.scan!=='running')return;state.scan='stopping';clearInterval(state.scanTimer);if(state.page==='clean')render();updateTaskChip();setTimeout(()=>{state.scan='cancelled';if(state.page==='clean')render();updateTaskChip();toast('已停止，已确认结果保留')},350)}
function viewPartial(){if(state.scan==='running'){state.cleanGroup='all';drawer('已确认结果','<div class="notice warn">任务仍在进行 · 部分范围未读取</div>'+candidates.slice(0,3).map(c=>'<div class="detail-fact"><span>'+c.name+'</span><b>'+size(c.amount)+'</b></div>').join(''),'<button class="primary" onclick="closeDrawer();route(\'disk\')">查看演示目录</button>')}else route('disk')}
function chooseScope(){if(['running','stopping'].includes(state.scan))return toast('请先结束当前扫描，再更换范围');modal('选择扫描范围','<label class="form-label" for="scope">本地范围</label><select id="scope" class="form-input"><option>C:/Users/Lin</option><option>D:/DemoProject</option><option>D:/Downloads</option></select><div class="notice">只读扫描 · 不跟随链接 · 不下载云内容</div>','<button class="primary" onclick="state.scanRoot=$(\'scope\').value;closeDialog();state.scan=\'idle\';render()">使用此范围</button>')}
function scanGaps(){drawer('未读取的范围','<div class="detail-fact"><span>System Volume Information</span><b>权限不足</b></div><div class="detail-fact"><span>OneDrive 占位目录</span><b>云边界未验证</b></div><div class="notice warn">未读取大小保持未知，不计为 0。</div>','<button onclick="closeDrawer();route(\'settings\');state.settingsTab=\'capabilities\';render()">权限与能力说明</button>')}
function selectCandidate(id,on){const c=getCandidate(id);if(!c||!eligible(c))return;on?state.selected.add(id):state.selected.delete(id);updateSelectionBar()}
function selectVisibleCandidates(){candidates.filter(c=>(state.cleanGroup==='all'||c.group===state.cleanGroup)&&eligible(c)).forEach(c=>state.selected.add(c.id));render()}
function candidateDetail(id){const c=getCandidate(id);drawer(c.name,'<span class="badge">'+(eligible(c)?'演示规则':'保留')+'</span><div class="detail-path">'+esc(c.root)+'</div><div class="detail-fact"><span>所属</span><b>'+c.owner+'</b></div><div class="detail-fact"><span>逻辑量</span><b>'+size(c.amount)+'</b></div><div class="detail-fact"><span>规则</span><b>'+c.rule+'</b></div><p class="muted">'+c.proof+'</p><div class="notice '+(!eligible(c)?'warn':'')+'">'+c.impact+'</div>',eligible(c)?'<button class="primary" onclick="selectCandidate(\''+id+'\',true);closeDrawer();render()">加入选择</button>':'<button onclick="closeDrawer()">保留现状</button>')}
function aiPage(){return heading('AI 与开发者','缓存、会话、工作树与模型分别查看','<button onclick="route(\'disk\')">查看空间分布 ↗</button>')+'<div class="controls"><div class="chips">'+[['cache','可重建缓存'],['sessions','会话与工作树'],['models','模型库']].map(([key,n])=>'<button class="'+(state.aiTab===key?'active':'')+'" onclick="state.aiTab=\''+key+'\';render()">'+n+'</button>').join('')+'</div></div>'+(state.aiTab==='cache'?'<div class="three-col">'+['Codex','Claude Code','Cursor'].map((n,i)=>'<div class="panel"><div class="row" style="padding-top:0">'+icon(['✧','C','↗'][i])+'<div class="row-main"><h3 style="margin:0">'+n+'</h3><div class="row-meta">演示工具安装实例</div></div></div><div class="stat-value">'+(i===0?'180':i===1?'未识别':'420')+' <small>'+(i===1?'':'MiB')+'</small></div><div class="muted">会话、设置与模型保留</div></div>').join('')+'</div><section class="panel section-gap"><h2>可审阅内容</h2>'+candidates.filter(c=>c.group==='ai'||c.id==='build').map(candidateRow).join('')+'</section>':state.aiTab==='sessions'?'<div class="split"><div class="panel"><h2>会话与工作树</h2>'+[['Codex 会话','118 条 · 870 MiB','思路与历史'],['Claude Code 项目会话','42 条 · 310 MiB','项目上下文'],['开发工作树','8 个 · 2.4 GiB','其中 3 个有未提交修改']].map(([n,v,d])=>'<div class="row">'+icon('⌘')+'<div class="row-main"><div class="row-name">'+n+'</div><div class="row-meta">'+v+' · '+d+'</div></div><span class="pill">保留</span><button class="ghost" onclick="sessionDetail(\''+n+'\')">查看 ›</button></div>').join('')+'</div><aside class="panel"><h2>保留策略</h2><div class="row"><span>当前模式</span><b>保留全部</b></div><div class="notice">时间与大小不构成删除依据</div><button onclick="sessionDetail(\'会话与工作树\')">查看管理概念</button></aside></div>':'<div class="panel"><h2>模型占用</h2>'+[['Ollama','28.0 GiB','共享数据块'],['Hugging Face','12.0 GiB','来源与独占块未完全确认']].map(([n,v,d])=>'<div class="row">'+icon('▧')+'<div class="row-main"><div class="row-name">'+n+'</div><div class="row-meta">'+d+'</div></div><b>'+v+'</b><span class="pill">保留</span><button onclick="modelDetail(\''+n+'\')">查看</button></div>').join('')+'<div class="notice">模型目录大小不等于可释放量</div></div>')}
function sessionDetail(name){drawer(name,'<div class="badge">用户成果 · 保留</div><div class="detail-fact"><span>最近使用</span><b>今天</b></div><div class="detail-fact"><span>工作树变化</span><b>3 个有未提交修改</b></div><div class="notice">现有首版保护会话、配置与工作树。</div><p class="muted">后续会话归档与工具维护应通过各工具原生能力，单独计划并审阅。</p>','<button onclick="toast(\'已定位演示用户数据目录\')">定位数据目录</button>')}
function modelDetail(name){drawer(name,'<div class="detail-fact"><span>逻辑量</span><b>'+(name==='Ollama'?'28.0':'12.0')+' GiB</b></div><div class="detail-fact"><span>预计释放</span><b>未知</b></div><div class="notice">共享块与引用关系由工具自身管理。</div>','<button class="primary" onclick="closeDrawer();state.diskPath=[tree];state.diskSelected=\'models\';route(\'disk\')">在磁盘中查看</button>')}
function appsPage(){const titles={installed:'安装实例',updates:'更新',startup:'启动项'};const q=state.appSearch.toLowerCase();let list=applications.filter(a=>(a.name+' '+a.source+' '+a.path).toLowerCase().includes(q)&&(state.appFilter==='all'||state.appFilter==='cache'&&a.items.some(id=>eligible(getCandidate(id)))||state.appFilter==='shared'&&a.shared));if(state.appSort==='size')list.sort((a,b)=>b.amount-a.amount);if(state.appSort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));return heading('应用','本体、关联内容与来源证据','<button onclick="toast(\'演示应用清单已刷新\')">刷新 ↻</button>')+'<div class="tabs">'+Object.entries(titles).map(([id,n])=>'<button class="'+(state.appTab===id?'active':'')+'" onclick="state.appTab=\''+id+'\';render()">'+n+(id!=='installed'?' <span class="badge concept">概念</span>':'')+'</button>').join('')+'</div>'+(state.appTab==='installed'?'<div class="controls"><label class="search">⌕ <input aria-label="搜索应用" placeholder="搜索应用、来源或位置" value="'+esc(state.appSearch)+'" oninput="appSearch(this.value)"></label><div class="chips">'+[['all','全部'],['cache','缓存候选'],['shared','共享数据']].map(([id,n])=>'<button class="'+(state.appFilter===id?'active':'')+'" onclick="state.appFilter=\''+id+'\';render()">'+n+'</button>').join('')+'</div><select aria-label="应用排序" onchange="state.appSort=this.value;render()"><option value="default" '+(state.appSort==='default'?'selected':'')+'>默认顺序</option><option value="size" '+(state.appSort==='size'?'selected':'')+'>已知占用 ↓</option><option value="name" '+(state.appSort==='name'?'selected':'')+'>名称</option></select></div><div class="split"><section class="panel app-list"><div class="list-head"><span>'+list.length+' 个安装实例</span><span>已知独占空间</span></div>'+list.map(a=>'<article class="app-row '+(state.expandedApp===a.id?'expanded':'')+'"><button class="app-row-button" aria-expanded="'+(state.expandedApp===a.id)+'" onclick="state.expandedApp=state.expandedApp===\''+a.id+'\'?null:\''+a.id+'\';render()"><span class="tiny-icon app-icon" style="background:'+a.color+'">'+a.icon+'</span><div class="row-main"><div class="row-name">'+a.name+'</div><div class="row-meta">'+a.version+' · '+a.source+(a.id==='portable'?' · D:/Apps':'')+'</div></div><div class="row-size">'+size(a.amount)+'</div><span class="muted">'+(state.expandedApp===a.id?'⌄':'›')+'</span></button>'+(state.expandedApp===a.id?'<div class="app-expand">'+(a.items.length?a.items.map(id=>candidateRow(getCandidate(id))).join(''):'<div class="row"><span class="muted">暂无已确认缓存候选</span><span class="pill">仅分析</span></div>')+'<div class="row"><span class="muted">用户数据 · '+size(a.user)+'</span><span class="pill">保留</span></div>'+(a.shared?'<div class="row"><span class="muted">共享目录 · 不计入独占</span><span class="pill">保留</span></div>':'')+'<div class="row"><button class="ghost" onclick="appDetail(\''+a.id+'\')">来源与安装位置 ↗</button><button class="ghost" onclick="uninstallConcept(\''+a.id+'\')">卸载检查 <span class="badge concept">概念</span></button></div></div>':'')+'</article>').join('')+(list.length?'':'<div class="empty-state">没有匹配项</div>')+'</section><aside class="panel"><h2>应用关联</h2><div class="row"><span class="muted">安装实例</span><span>分别识别</span></div><div class="row"><span class="muted">共享 / 未知</span><span>保持保留</span></div><div class="notice">应用身份不等于清理授权</div><button style="width:100%" onclick="route(\'disk\')">查看磁盘 ↗</button></aside></div>':state.appTab==='updates'?'<div class="panel"><h2>可查看的更新</h2>'+[['vscode','1.93 → 1.94','厂商更新器'],['chrome','129 → 130','包管理器来源']].map(([id,v,source])=>'<div class="row">'+icon(applications.find(a=>a.id===id).icon)+'<div class="row-main"><div class="row-name">'+applications.find(a=>a.id===id).name+'</div><div class="row-meta">'+v+' · '+source+'</div></div><button onclick="updateConcept(\''+id+'\')">审阅更新</button></div>').join('')+'<div class="notice">扩展交互仅模拟原生更新器交接。</div></div>':'<div class="panel"><h2>启动与后台项目</h2>'+[['Docker Desktop','登录时打开 · 有来源证据'],['未知后台项目','来源未确认 · 仅查看']].map(([n,d],i)=>'<div class="row">'+icon(i?'?':'D')+'<div class="row-main"><div class="row-name">'+n+'</div><div class="row-meta">'+d+'</div></div>'+(i?'<span class="pill">待判断</span>':'<button onclick="startupConcept()">查看管理</button>')+'</div>').join('')+'</div>')}
function appSearch(value){state.appSearch=value;const start=document.activeElement.selectionStart;render();const e=document.querySelector('input[aria-label="搜索应用"]');e.focus();e.setSelectionRange(start,start)}
function appDetail(id){const a=applications.find(a=>a.id===id);drawer(a.name,'<span class="badge">'+a.source+'</span><div class="detail-path">'+a.path+'</div><div class="detail-fact"><span>应用本体</span><b>'+size(a.base)+'</b></div><div class="detail-fact"><span>用户数据</span><b>'+size(a.user)+' · 保留</b></div><div class="detail-fact"><span>共享关联</span><b>'+(a.shared?'共享另列':'未确认共享')+'</b></div><div class="detail-fact"><span>覆盖</span><b>部分 · 今天 10:24</b></div>','<button class="primary" onclick="closeDrawer();route(\'disk\')">在磁盘中定位</button>')}
function uninstallConcept(id){const a=applications.find(a=>a.id===id);modal('卸载检查 · 扩展概念','<div class="row">'+icon(a.icon)+'<div class="row-main"><h3>'+a.name+'</h3><span class="muted">'+a.source+'</span></div></div><div class="row"><span>应用本体</span><b>'+size(a.base)+'</b></div><div class="row"><span>个人数据与共享目录</span><b>默认保留</b></div><div class="notice">交给原生卸载器；相关缓存另行审阅。</div>','<button class="primary" onclick="makePlan(\'uninstall\',[{id:\''+id+'\',name:\''+a.name+'\',amount:'+a.base+'}],{mode:\'原生卸载器\',concept:true})">创建卸载交接计划</button>')}
function updateConcept(id){const a=applications.find(a=>a.id===id);modal('更新审阅 · '+a.name,'<div class="detail-fact"><span>更新来源</span><b>厂商 / 包管理器 · 演示</b></div><div class="notice">安装器的实际副作用需独立记录；更新不承诺撤销。</div>','<button class="primary" onclick="makePlan(\'update\',[{id:\''+id+'\',name:\''+a.name+' 更新\',amount:null}],{mode:\'原生更新器\',concept:true})">创建更新交接计划</button>')}
function startupConcept(){modal('登录项管理 · 扩展概念','<div class="detail-fact"><span>来源</span><b>系统登录项 · 演示</b></div><div class="detail-fact"><span>对象</span><b>Docker Desktop</b></div><div class="notice">未知项目保持只读；更改只影响明确的登录入口。</div>','<button class="primary" onclick="closeDialog();toast(\'已模拟关闭 Docker 登录项\')">模拟关闭登录项</button>')}
function diskItems(){let a=state.diskPath.at(-1).children||[];a=a.filter(n=>n.name.toLowerCase().includes(state.diskSearch.toLowerCase()));return [...a].sort(state.diskSort==='name'?(a,b)=>a.name.localeCompare(b.name):(a,b)=>(b[state.diskMetric]??-1)-(a[state.diskMetric]??-1))}
function layoutRects(items,x=0,y=0,w=100,h=100){if(!items.length)return[];if(items.length===1)return[{node:items[0],x,y,w,h}];const total=items.reduce((n,a)=>n+a[state.diskMetric],0);let i=1,left=items[0][state.diskMetric];while(i<items.length-1&&left<total/2){left+=items[i][state.diskMetric];i++}const r=left/total;return w>=h?[...layoutRects(items.slice(0,i),x,y,w*r,h),...layoutRects(items.slice(i),x+w*r,y,w*(1-r),h)]:[...layoutRects(items.slice(0,i),x,y,w,h*r),...layoutRects(items.slice(i),x,y+h*r,w,h*(1-r))]}
function diskPage(){const node=state.diskPath.at(-1),a=diskItems(),known=a.filter(n=>n[state.diskMetric]!==null&&n[state.diskMetric]>0),colors=['#a8cbb8','#cbd6b1','#a9c9d8','#dfceab','#c6bbd8','#d9bfbd','#bfd3cf'];return heading('磁盘分析','色块与目录表来自同一演示快照','<button onclick="chooseScope()">选择范围</button>')+'<div class="disk-breadcrumb">'+state.diskPath.map((n,i)=>'<button onclick="state.diskPath=state.diskPath.slice(0,'+(i+1)+');state.diskSelected=null;state.diskSearch=\'\';render()">'+n.name+'</button>'+(i<state.diskPath.length-1?'<span class="muted">/</span>':'')).join('')+'</div><div class="controls"><div class="chips"><button class="'+(state.diskMetric==='amount'?'active':'')+'" onclick="state.diskMetric=\'amount\';render()">逻辑大小</button><button class="'+(state.diskMetric==='allocated'?'active':'')+'" onclick="state.diskMetric=\'allocated\';render()">分配大小</button></div><label class="search">⌕ <input aria-label="筛选目录" placeholder="筛选当前目录" value="'+esc(state.diskSearch)+'" oninput="diskSearch(this.value)"></label><select aria-label="目录排序" onchange="state.diskSort=this.value;render()"><option value="size" '+(state.diskSort==='size'?'selected':'')+'>大小 ↓</option><option value="name" '+(state.diskSort==='name'?'selected':'')+'>名称</option></select><button onclick="state.diskView=state.diskView===\'table\'?\'both\':\'table\';render()">'+(state.diskView==='table'?'显示色块':'仅表格')+'</button></div><div class="split"><section class="panel">'+(state.diskView==='both'?'<div class="treemap" aria-label="已知空间色块">'+layoutRects(known).map((r,i)=>'<button style="left:'+r.x+'%;top:'+r.y+'%;width:'+r.w+'%;height:'+r.h+'%;background:'+colors[i%colors.length]+'" class="'+(state.diskSelected===r.node.id?'active':'')+'" onclick="selectDisk(\''+r.node.id+'\')" ondblclick="drillDisk(\''+r.node.id+'\')" oncontextmenu="diskMenu(event,\''+r.node.id+'\')" aria-label="'+r.node.name+' '+size(r.node[state.diskMetric])+'"><b>'+r.node.name+'</b><small>'+size(r.node[state.diskMetric])+'</small></button>').join('')+'</div>':'')+(a.some(n=>n[state.diskMetric]===null)?'<div class="notice warn"><span>未知空间单列，不分配虚构面积</span><button onclick="scanGaps()">查看原因 ›</button></div>':'')+'<table class="disk-table"><thead><tr><th>名称</th><th class="num">'+(state.diskMetric==='amount'?'逻辑大小':'分配大小')+'</th><th>状态</th><th></th></tr></thead><tbody>'+a.map(n=>'<tr class="'+(state.diskSelected===n.id?'active':'')+'"><td><button onclick="selectDisk(\''+n.id+'\')">▱ '+n.name+'</button></td><td class="num">'+size(n[state.diskMetric])+'</td><td><span class="muted">'+(n.reason||n.protected?'保留 / 边界':'仅分析')+'</span></td><td>'+(n.children?'<button onclick="drillDisk(\''+n.id+'\')">打开 ›</button>':'<button onclick="diskDetail(\''+n.id+'\')">详情 ›</button>')+'</td></tr>').join('')+'</tbody></table></section><aside class="panel"><h2>'+node.name+'</h2><div class="stat-value">'+size(node[state.diskMetric])+'</div><p class="muted">声明范围内已知量，不作为清理收益。</p><div class="row"><span>扫描时间</span><span>今天 10:24</span></div><div class="row"><span>覆盖</span><span>部分</span></div><div class="notice">点击选择 · 双击进入目录</div>'+(state.diskPath.length>1?'<button onclick="state.diskPath.pop();state.diskSelected=null;render()">返回上一级</button>':'<button onclick="route(\'clean\')">查看规则候选</button>')+'</aside></div>'}
function diskSearch(value){state.diskSearch=value;const pos=document.activeElement.selectionStart;render();const e=document.querySelector('input[aria-label="筛选目录"]');e.focus();e.setSelectionRange(pos,pos)}
function findDisk(id){function find(n){if(n.id===id)return n;for(const c of n.children||[]){const r=find(c);if(r)return r}return null}return find(tree)}
function selectDisk(id){state.diskSelected=id;render();diskDetail(id)}
function drillDisk(id){const n=findDisk(id);if(n?.children){closeDrawer();state.diskPath.push(n);state.diskSelected=null;state.diskSearch='';render()}else diskDetail(id)}
function diskDetail(id){const n=findDisk(id);drawer(n.name,'<div class="detail-path">'+state.diskPath.map(n=>n.name).join(' / ')+' / '+n.name+'</div><div class="detail-fact"><span>逻辑大小</span><b>'+size(n.amount)+'</b></div><div class="detail-fact"><span>分配大小</span><b>'+size(n.allocated)+'</b></div><div class="detail-fact"><span>归属 / 状态</span><b>'+(n.reason||n.owner||n.protected&&'用户成果 · 保留'||'待判断')+'</b></div><div class="notice">'+(n.candidate?'关联演示规则；需审阅计划':'大文件浏览不授予删除能力')+'</div>',(n.children?'<button class="primary" onclick="drillDisk(\''+id+'\')">打开目录</button>':'')+(n.candidate?'<button onclick="candidateDetail(\''+n.candidate+'\')">查看关联候选</button>':'')+'<button onclick="state.protectedPaths.add(\''+id+'\');toast(\'已添加演示保护路径\')">添加保护</button>')}
function diskMenu(e,id){e.preventDefault();const n=findDisk(id),m=$('contextMenu');m.innerHTML='<button onclick="diskDetail(\''+id+'\');$(\'contextMenu\').hidden=true">查看详情</button>'+(n.children?'<button onclick="drillDisk(\''+id+'\');$(\'contextMenu\').hidden=true">打开目录</button>':'')+'<button onclick="state.protectedPaths.add(\''+id+'\');toast(\'已添加保护\');$(\'contextMenu\').hidden=true">添加保护</button>'+(n.candidate?'<button onclick="candidateDetail(\''+n.candidate+'\');$(\'contextMenu\').hidden=true">查看关联候选</button>':'');m.style.left=Math.min(e.clientX,window.innerWidth-190)+'px';m.style.top=Math.min(e.clientY,window.innerHeight-190)+'px';m.hidden=false}
function maintenancePage(){return heading('维护','按具体问题选择任务，逐项查看结果','<button onclick="maintenanceInfo()">平台差异</button>',true)+'<div class="split"><section class="panel"><h2>需要处理什么</h2>'+maintenanceTasks.map(t=>'<div class="maintenance-item"><label><input type="checkbox" '+(state.maintenance.has(t.id)?'checked':'')+' '+(!t.enabled||t.platform!==state.system&&t.platform!=='双平台'?'disabled':'')+' onchange="this.checked?state.maintenance.add(\''+t.id+'\'):state.maintenance.delete(\''+t.id+'\');render()"><span class="row-main"><span class="row-name">'+t.name+'</span><span class="row-meta" style="display:block">'+t.detail+'</span></span></label><span class="pill">'+t.platform+'</span><button class="ghost" onclick="maintenanceDetail(\''+t.id+'\')">›</button></div>').join('')+'<div class="row"><span class="muted">'+state.maintenance.size+' 项已选</span><button class="primary" '+(!state.maintenance.size?'disabled':'')+' onclick="createMaintenance()">审阅维护计划 →</button></div></section><aside class="panel"><h2>先看影响</h2><div class="row"><span>当前平台</span><b>'+state.system+'</b></div><div class="row"><span>设备状态未知</span><span>跳过相关任务</span></div><div class="row"><span>系统读取权限</span><span>独立判断</span></div><div class="notice">手动启动，完成即停止</div><p class="muted">不以“健康分”或未经测量的加速作为结果。</p></aside></div>'}
function maintenanceInfo(){modal('维护能力与平台','<div class="row"><span>Windows</span><b>图标 / DNS 等固定任务</b></div><div class="row"><span>macOS</span><b>Quick Look / DNS 等固定任务</b></div><div class="notice warn">扩展概念。实际操作需要独立的平台能力与授权验证。</div>')}
function maintenanceDetail(id){const t=maintenanceTasks.find(x=>x.id===id);drawer(t.name,'<div class="detail-fact"><span>动作</span><b>'+t.detail+'</b></div><div class="detail-fact"><span>适用</span><b>'+t.platform+'</b></div><div class="notice">'+t.impact+'</div>','<button onclick="closeDrawer()">了解</button>')}
function createMaintenance(){const items=maintenanceTasks.filter(t=>state.maintenance.has(t.id)).map(t=>({id:t.id,name:t.detail,amount:null}));if(items.length)makePlan('maintenance',items,{mode:'固定维护任务',concept:true})}
function spark(seed){const values=Array.from({length:28},(_,i)=>26-Math.sin(i*.52+seed)*8-Math.cos(i*.19+seed)*7);return '<svg class="sparkline" viewBox="0 0 200 45" preserveAspectRatio="none" aria-hidden="true"><polyline fill="none" stroke="currentColor" stroke-width="1.8" points="'+values.map((v,i)=>(i*200/27)+','+v).join(' ')+'"></polyline></svg>'}
function statusPage(){let proc=processData.filter(p=>p.name.toLowerCase().includes(state.processSearch.toLowerCase()));proc.sort((a,b)=>Number(state.processPinned.has(b.id))-Number(state.processPinned.has(a.id))||(state.processSort==='memory'?b.memory-a.memory:b.cpu-a.cpu));return heading('状态','演示指标 · 读数与近期趋势同时查看','<select aria-label="趋势时间范围" onchange="state.statusRange=this.value;render()"><option value="60" '+(state.statusRange==='60'?'selected':'')+'>最近 60 秒</option><option value="300" '+(state.statusRange==='300'?'selected':'')+'>最近 5 分钟</option></select>',true)+'<div class="metric-grid">'+[['CPU','28','%',1],['内存','8.2','/ 16 GiB',2],['GPU','12','%',3],['磁盘读取','24','MiB/s',4],['网络接收','1.8','MiB/s',5],['电池','86','%',6]].map(([n,v,u,seed])=>card(n,v,u,spark(seed+(state.statusRange==='300'?2:0)))).join('')+'</div><section class="panel section-gap"><div class="controls"><h2 style="margin:0 auto 0 0">进程</h2><label class="search">⌕ <input aria-label="搜索进程" placeholder="搜索进程" value="'+esc(state.processSearch)+'" oninput="processSearch(this.value)"></label><select aria-label="进程排序" onchange="state.processSort=this.value;render()"><option value="cpu" '+(state.processSort==='cpu'?'selected':'')+'>CPU ↓</option><option value="memory" '+(state.processSort==='memory'?'selected':'')+'>内存 ↓</option></select></div><div class="process-row process-head"><span>名称 / 用途</span><span>CPU</span><span>内存</span><span>PID</span></div>'+proc.map(p=>'<div class="process-row"><button onclick="processDetail('+p.id+')">'+(state.processPinned.has(p.id)?'⌖ ':'')+p.name+'<span class="row-meta" style="display:block">'+p.purpose+'</span></button><span>'+p.cpu+' %</span><span>'+size(p.memory)+'</span><span>'+p.id+'</span></div>').join('')+'</section>'}
function processSearch(value){state.processSearch=value;const pos=document.activeElement.selectionStart;render();const e=document.querySelector('input[aria-label="搜索进程"]');e.focus();e.setSelectionRange(pos,pos)}
function processDetail(id){const p=processData.find(p=>p.id===id);drawer(p.name,'<p class="muted">'+p.purpose+'</p><div class="detail-fact"><span>CPU</span><b>'+p.cpu+' %</b></div><div class="detail-fact"><span>内存</span><b>'+size(p.memory)+'</b></div><div class="detail-path">'+p.path+'</div>','<button class="primary" onclick="state.processPinned.has('+id+')?state.processPinned.delete('+id+'):state.processPinned.add('+id+');closeDrawer();render()">切换置顶</button><button onclick="toast(\'演示可执行文件路径：'+esc(p.path)+'\')">查看路径</button>')}
function showTray(){modal('快捷状态','<span class="badge concept">状态扩展 · 演示指标</span><div class="tray-grid"><div class="panel"><div class="label">CPU</div><b>28 %</b>'+spark(1)+'</div><div class="panel"><div class="label">内存</div><b>8.2 GiB</b>'+spark(2)+'</div></div><div class="row"><span>保持常亮 · 演示开关</span>'+toggle('sleep',state.sleep)+'</div><div class="row"><span>温度与风扇</span><span class="pill">当前未验证</span></div>','<button class="primary" onclick="closeDialog();route(\'status\')">打开状态页</button>')}
function makePlan(kind,items,opts={}){if(!items.length)return toast('请先选择内容');closeDialog();closeDrawer();state.planCounter++;const plan={id:'P-DEMO-'+String(state.planCounter).padStart(3,'0'),kind,items:Object.freeze(items.map(i=>Object.freeze({...i}))),mode:opts.mode||'同卷隔离',concept:!!opts.concept,created:Date.now(),expires:Date.now()+900000,status:'等待审阅',destination:opts.destination||null};state.plans.unshift(plan);state.currentPlan=plan.id;route('plans');render()}
function createCachePlan(){const items=selectedItems();if(items.length)makePlan('cache',items)}
function activePlan(){return state.plans.find(p=>p.id===state.currentPlan)||state.plans[0]}
function policyMatches(plan){return state.preauth&&plan.kind==='cache'&&plan.mode==='同卷隔离'&&plan.items.length<=1000&&plan.items.every(i=>i.root===state.policyRoot)&&plan.items.reduce((n,i)=>n+(i.amount||0),0)<=1024}
function plansPage(){const p=activePlan();if(!p)return heading('操作计划','人工与 Agent 共用固定对象清单','<button onclick="agentHandoff()">体验 Agent 交接</button>')+empty('还没有计划','从清理、应用或 AI 页面选择候选。','<button class="primary" onclick="route(\'clean\')">前往清理</button>');const expired=Date.now()>=p.expires||state.scenario==='expired',approved=policyMatches(p);return heading('审阅计划','固定对象集合 · '+p.id+(p.concept?' · 扩展概念':''),'<button onclick="agentHandoff()">Agent 交接</button><button onclick="showPlans()">全部计划</button>')+'<div class="split"><section class="panel"><div class="inline-actions"><span class="badge">'+(expired?'已过期':p.status)+'</span>'+(approved?'<span class="badge">有限策略覆盖</span>':'')+'</div><div class="summary-stats"><div><b>'+p.items.length+'</b><small>固定对象</small></div><div><b>'+size(p.items.some(i=>i.amount===null)?null:p.items.reduce((n,i)=>n+i.amount,0))+'</b><small>处理逻辑量</small></div><div><b>'+(expired?'已过期':'15 分钟')+'</b><small>演示有效期</small></div></div>'+(p.kind==='cache'?'<div class="mode-controls">'+['同卷隔离','回收站','永久删除'].map(m=>'<button class="'+(p.mode===m?'active':'')+'" '+(p.status!=='等待审阅'?'disabled':'')+' onclick="replacePlanMode(\''+m+'\')">'+m+'</button>').join('')+'</div>':'<div class="row"><span class="muted">方式</span><b>'+p.mode+'</b></div>')+'<div class="notice '+(p.mode==='永久删除'||p.kind==='purge'?'warn':'')+'">'+modeExplanation(p)+(p.destination?' · 目标 '+esc(p.destination):'')+'</div>'+p.items.map(i=>'<div class="row"><div class="row-main"><div class="row-name">'+esc(i.name)+'</div><div class="row-meta">'+esc(i.owner||i.original||i.root||'固定演示对象')+'</div></div><b>'+size(i.amount)+'</b></div>').join('')+(expired?'<div class="row"><span class="muted">旧计划保留</span><button class="primary" onclick="regeneratePlan()">重新生成计划</button></div>':p.status==='等待审阅'?'<label class="review-consent"><input id="consent" type="checkbox" '+(approved?'checked disabled':'')+' onchange="$(\'applyPlan\').disabled=!this.checked">'+(approved?'已由有限策略授权':'我已审阅对象、模式和恢复限制')+'</label><div class="row"><button onclick="route(\'clean\')">返回选择</button><button id="applyPlan" class="primary" '+(!approved?'disabled':'')+' onclick="applyPlan(\''+p.id+'\')">'+(approved?'按策略执行':'授权并执行')+' · 演示</button></div>':'<div class="row"><span>'+p.status+'</span><button class="primary" onclick="viewOperation(\''+p.id+'\')">查看执行结果</button></div>')+'</section><aside class="panel"><h2>计划信息</h2><div class="row"><span>来源</span><span>'+p.kind+'</span></div><div class="row"><span>授权</span><span>'+(approved?'精确根策略':'人工审阅')+'</span></div><div class="row"><span>摘要</span><button class="ghost" onclick="planInfo(\''+p.id+'\')">查看 ›</button></div><p class="muted">变更内容或模式生成新计划，旧记录仍可查询。</p></aside></div>'}
function modeExplanation(p){return p.kind==='restore'?'独立恢复授权 · '+(p.destination?'使用明确的新目标':'原位置不覆盖冲突'):p.kind==='purge'?'永久清空 · 不可恢复 · 与隔离授权独立':p.kind==='maintenance'?'固定维护项目 · 跳过不适用任务':p.kind==='uninstall'||p.kind==='update'?'模拟原生工具交接 · 不承诺逐文件撤销':p.mode==='同卷隔离'?'可恢复 · 同卷隔离不立即释放空间':p.mode==='回收站'?'由系统回收站管理恢复 · 不承诺立即释放空间':'永久删除 · 不可恢复'}
function replacePlanMode(mode){const p=activePlan();if(p.status!=='等待审阅'||p.mode===mode)return;makePlan(p.kind,p.items,{mode,concept:p.concept});toast('模式已改变，已生成新计划')}
function regeneratePlan(){const p=activePlan();state.scenario='normal';makePlan(p.kind,p.items,{mode:p.mode,concept:p.concept,destination:p.destination})}
function planInfo(id){const p=state.plans.find(p=>p.id===id);drawer('计划信息','<div class="detail-fact"><span>计划 ID</span><b>'+p.id+'</b></div><div class="detail-fact"><span>对象集合</span><b>'+p.items.length+' 项 · 固定</b></div><div class="detail-fact"><span>方式</span><b>'+p.mode+'</b></div><div class="code-snippet">演示摘要：'+p.id+' / '+p.kind+' / '+p.mode+'<br>正式实现使用规范化 SHA-256；这里不伪造真实摘要。</div>','<button onclick="closeDrawer()">返回审阅</button>')}
function showPlans(){modal('全部演示计划','<div class="plan-list">'+state.plans.map(p=>'<button onclick="state.currentPlan=\''+p.id+'\';closeDialog();route(\'plans\');render()"><span class="row-main"><b>'+p.id+'</b><div class="row-meta">'+p.mode+' · '+p.items.length+' 项</div></span><span class="pill">'+p.status+'</span><span>›</span></button>').join('')+'</div>')}
function agentHandoff(){modal('Agent 交接','<div class="notice">人工与 Agent 审阅同一计划，不重建近似清单。</div><div class="code-snippet">能力 → 扫描 → 候选 → 计划<br>needs_approval → 人工审阅 → 执行 → 报告</div>','<button class="primary" onclick="makePlan(\'cache\',[getCandidate(\'temp\')]);toast(\'演示 Agent 计划已进入审阅入口\')">打开示例 Agent 计划</button>')}
function applyPlan(id){const p=state.plans.find(x=>x.id===id);if(!p)return;if(p.status!=='等待审阅'){viewOperation(id);return toast('返回已有执行，不重复处理')}if(state.operation?.status==='running')return toast('已有执行正在进行');if(Object.values(state.operations).some(op=>op.status==='unknown'&&op.items.some(i=>p.items.some(t=>t.id===i.id))))return toast('重叠对象仍需核对，暂不执行');if(Date.now()>=p.expires||state.scenario==='expired')return toast('计划已过期，请重新生成');p.status='执行中';state.operation={planId:id,items:p.items,mode:p.mode,kind:p.kind,destination:p.destination,index:0,results:[],status:'running',phase:'现场复核',stop:false};state.operations[id]=state.operation;state.viewOperationId=id;route('run');setTimeout(()=>{const op=state.operation;if(!op||op.planId!==id||op.status!=='running')return;op.phase='执行';state.operationTimer=setInterval(executionTick,650);render()},500)}
function executionTick(){const op=state.operation;if(!op||op.status!=='running'){clearInterval(state.operationTimer);return}if(op.stop){op.status='cancelled';finishOperation();return}if(state.scenario==='interrupt'&&op.index===Math.min(1,op.items.length-1)){op.results.push({item:op.items[op.index],status:'unknown',reason:'演示中断 · 需要核对'});op.index++;op.status='unknown';finishOperation();return}const item=op.items[op.index];const stale=state.scenario==='changed'&&op.index===0||op.kind==='cache'&&(state.removed.has(item.id)||candidateProtected(item));op.results.push({item,status:stale?'skipped':'success',reason:stale?'身份 / 条件变化':'已确认'});if(!stale&&op.kind==='cache'){state.removed.add(item.id);if(op.mode==='同卷隔离')state.recovery.push({id:'R-'+op.planId+'-'+item.id,name:item.name,amount:item.amount,original:item.root,date:'刚刚',conflict:false,candidate:item.id})}if(!stale&&['restore','purge'].includes(op.kind)){state.recovery=state.recovery.filter(r=>r.id!==item.id);state.recoverySelection.delete(item.id);if(op.kind==='restore'&&!op.destination&&item.candidate)state.removed.delete(item.candidate)}op.index++;if(op.index>=op.items.length){op.status=op.results.some(r=>r.status==='skipped')?'partial':'completed';finishOperation()}else if(state.page==='run')render();else updateTaskChip()}
function finishOperation(){clearInterval(state.operationTimer);const op=state.operation,p=state.plans.find(p=>p.id===op.planId);p.status=op.status==='unknown'?'需要核对':op.status==='cancelled'?'已取消':op.status==='partial'?'部分完成':'已完成';state.history.unshift({id:'H-'+op.planId,title:p.mode+' · '+p.items.length+' 项',time:'刚刚',status:p.status,kind:op.status==='unknown'?'unknown':p.kind,planId:p.id,amount:p.items.reduce((n,i)=>n+(i.amount||0),0)});p.items.forEach(i=>state.selected.delete(i.id));if(state.page==='run')render();else{render();toast(p.status+' · 查看活动记录')}}
function stopOperation(){if(state.operation?.status==='running'){state.operation.stop=true;state.operation.phase='停止中';if(state.page==='run')render();updateTaskChip()}}
function viewOperation(id){state.viewOperationId=id;route('run');render()}
function runPage(){const op=state.operations[state.viewOperationId]||state.operation;if(!op)return heading('执行与结果')+empty('暂无执行','先选择候选并审阅计划。','<button onclick="route(\'plans\')">打开计划</button>');const p=state.plans.find(p=>p.id===op.planId),running=op.status==='running',success=op.results.filter(r=>r.status==='success').length,skipped=op.results.filter(r=>r.status==='skipped').length,unknown=op.results.filter(r=>r.status==='unknown').length;return heading(running?'正在处理':p.status,'演示执行 · '+op.planId,'<button onclick="state.currentPlan=\''+p.id+'\';route(\'plans\')">关联计划</button>')+'<div class="panel"><div class="row"><h2 style="margin:0">'+op.mode+'</h2><span class="badge">'+(running?op.phase:p.status)+'</span></div><progress max="'+op.items.length+'" value="'+op.index+'"></progress><div class="summary-stats"><div><b>'+success+'</b><small>成功</small></div><div><b>'+skipped+'</b><small>跳过</small></div><div><b>'+unknown+'</b><small>待核对</small></div><div><b>'+(op.items.length-op.index)+'</b><small>未开始</small></div></div>'+op.items.map((item,i)=>{const r=op.results[i];return '<div class="row"><span class="row-main">'+esc(item.name)+'</span><span class="pill '+(r?.status==='success'?'good':r?.status==='unknown'?'warn':'')+'">'+(r?r.status==='success'?'已确认':r.status==='unknown'?'待核对':'跳过':'未开始')+'</span><span class="muted">'+(r?.reason||'')+'</span></div>'}).join('')+'<div class="notice '+(unknown?'warn':'')+'">'+(unknown?'未知副作用先核对，不自动重试':modeExplanation(p))+'</div><div class="row"><span class="muted">'+(running?'导航不会取消任务':'此前完成的操作保留')+'</span>'+(running?'<button class="danger" onclick="stopOperation()">停止后续处理</button>':unknown?'<button class="primary" onclick="reconcile(\'H-'+op.planId+'\')">只读核对</button>':p.kind==='cache'&&p.mode==='同卷隔离'?'<button class="primary" onclick="route(\'recovery\')">查看隔离内容 →</button>':'<button onclick="route(\'activity\')">查看活动记录</button>')+'</div></div>'+(!running?'<div class="three-col section-gap">'+card('处理量',size(op.results.filter(r=>r.status==='success').reduce((n,r)=>n+(r.item.amount||0),0)))+card('预计释放',p.mode==='同卷隔离'?'不适用':'未知')+card('卷空闲观测','82.0 → 82.0','GiB','<p class="muted">演示观测 · 不全部归因于本工具</p>')+'</div>':'')}
function activityPage(){return heading('活动记录','时间、来源与逐项结果','<button onclick="toast(\'演示报告可在计划与结果页查询\')">查看报告说明</button>')+'<div class="panel">'+state.history.map(h=>'<div class="timeline-row '+(h.kind==='unknown'?'warning':'')+'"><span class="timeline-dot"></span><div class="row-main"><div class="row-name">'+h.title+'</div><div class="row-meta">'+h.time+' · '+size(h.amount)+'</div></div><span class="pill '+(h.kind==='unknown'?'warn':'')+'">'+h.status+'</span><button onclick="'+(h.kind==='unknown'?'reconcile(\''+h.id+'\')':h.planId?'state.currentPlan=\''+h.planId+'\';route(\'plans\')':'historyDetail(\''+h.id+'\')')+'">'+(h.kind==='unknown'?'核对':'详情')+' ›</button></div>').join('')+'</div>'}
function historyDetail(id){const h=state.history.find(h=>h.id===id);drawer(h.title,'<div class="detail-fact"><span>状态</span><b>'+h.status+'</b></div><div class="detail-fact"><span>时间</span><b>'+h.time+'</b></div><div class="detail-fact"><span>已知量</span><b>'+size(h.amount)+'</b></div>','<button onclick="closeDrawer();route(\'recovery\')">查看恢复</button>')}
function reconcile(id){const h=state.history.find(h=>h.id===id),op=state.operations[h?.planId],known=op?op.results.filter(r=>r.status!=='unknown').length:12,unknown=op?op.results.filter(r=>r.status==='unknown').length:1,remaining=op?op.items.length-op.index:27;modal('中断操作核对','<span class="badge">只读核对</span><div class="summary-stats"><div><b>'+known+'</b><small>已确认</small></div><div><b>'+unknown+'</b><small>待核对</small></div><div><b>'+remaining+'</b><small>未开始</small></div></div><div class="notice warn">先检查示例源 / 目标身份，不重放旧操作。</div>','<button class="primary" onclick="finishReconcile(\''+id+'\')">检查示例对象</button>')}
function finishReconcile(id){const h=state.history.find(h=>h.id===id),op=state.operations[h?.planId];if(h){h.status='核对完成';h.kind='reconciled'}if(op){op.results.forEach(r=>{if(r.status==='unknown'){r.status='skipped';r.reason='核对示例：源对象仍在，未执行'}});op.status='partial';state.plans.find(p=>p.id===h.planId).status='核对完成'}closeDialog();toast('演示核对已记录；后续动作另建计划');render()}
function recoveryPage(){return heading('隔离恢复','原位置、保留期限与恢复条件','<span class="badge">30 天后提醒 · 不自动清空</span>')+(state.recovery.length?'<div class="panel">'+state.recovery.map(r=>'<div class="check-row"><input type="checkbox" aria-label="选择恢复 '+r.name+'" '+(state.recoverySelection.has(r.id)?'checked':'')+' onchange="this.checked?state.recoverySelection.add(\''+r.id+'\'):state.recoverySelection.delete(\''+r.id+'\');render()"><div class="row-main"><div class="row-name">'+r.name+'</div><div class="row-meta">'+r.original+' · '+r.date+'</div></div>'+(r.conflict?'<span class="pill warn">原位置冲突</span>':'<span class="pill good">可恢复</span>')+'<span class="row-size">'+size(r.amount)+'</span></div>').join('')+'<div class="row"><span class="muted">'+state.recoverySelection.size+' 项已选</span><div class="inline-actions"><button class="danger" '+(!state.recoverySelection.size?'disabled':'')+' onclick="createRecovery(\'purge\')">清空计划</button><button class="primary" '+(!state.recoverySelection.size?'disabled':'')+' onclick="createRecovery(\'restore\')">恢复计划 →</button></div></div></div>':empty('没有隔离内容','隔离成功后可在这里审阅恢复条件。'))}
function createRecovery(kind,destination=null){const items=state.recovery.filter(r=>state.recoverySelection.has(r.id));if(!items.length)return;if(kind==='restore'&&destination&&items.some(r=>r.conflict&&(destination===r.original||destination===r.original.slice(0,r.original.lastIndexOf('/')))))return toast('该目标仍有同名文件，请选择其他位置');if(kind==='restore'&&!destination&&items.some(r=>r.conflict)){modal('原位置已有文件','<div class="notice warn">现有文件与隔离文件均保留，默认不覆盖。</div><div class="row"><span>现有 report.cache</span><b>今天 · 8 MiB</b></div><div class="row"><span>隔离 report.cache</span><b>昨天 · 8 MiB</b></div>','<button onclick="closeDialog()">保留现状</button><button class="primary" onclick="chooseRecoveryTarget()">选择其他位置</button>');return}makePlan(kind,items,{mode:kind==='restore'?'恢复':'永久清空',destination})}
function chooseRecoveryTarget(){modal('指定恢复位置','<label class="form-label" for="restorePath">新位置 · 演示路径</label><input class="form-input" type="text" id="restorePath" value="D:/Recovered"><div class="notice">目标变化生成独立计划，仍需授权。</div>','<button class="primary" onclick="confirmRecoveryTarget()">生成恢复计划</button>')}
function confirmRecoveryTarget(){const path=$('restorePath').value.trim();if(!path)return toast('请输入目标路径');createRecovery('restore',path)}
function settingsPage(){const tabs={general:'通用与外观',protection:'保护与隐私',capabilities:'平台与权限',policy:'Agent 与授权',demo:'演示场景'};return heading('设置','精简配置，按需展开')+'<div class="split settings-layout"><section class="panel settings-nav">'+Object.entries(tabs).map(([id,n])=>'<button class="'+(state.settingsTab===id?'active':'')+'" onclick="state.settingsTab=\''+id+'\';render()">'+n+'</button>').join('')+'</section><section class="panel">'+(state.settingsTab==='general'?'<h2>通用与外观</h2><div class="row"><span>深色外观</span><button onclick="switchTheme()">切换主题 ◐</button></div><div class="row"><span>减少动态效果</span>'+toggle('reduceMotion',state.reduceMotion)+'</div><div class="row"><span>完成通知 · 演示</span>'+toggle('notifications',state.notifications)+'</div><div class="row"><span>平台界面</span><select aria-label="演示平台" onchange="state.system=this.value;state.maintenance.clear();render()"><option '+(state.system==='Windows'?'selected':'')+'>Windows</option><option '+(state.system==='macOS'?'selected':'')+'>macOS</option></select></div><div class="notice">外观立即生效，平台切换只改变演示适用任务。</div>':state.settingsTab==='protection'?'<h2>保护与隐私</h2>'+[...state.protectedPaths].map(p=>'<div class="row"><span style="overflow-wrap:anywhere">'+esc(p)+'</span><span class="pill">保护</span></div>').join('')+'<div class="row"><button onclick="addProtection()">添加保护路径</button><span class="muted">凭据 / 会话 / 用户成果默认保留</span></div><div class="row"><span>遥测 · 默认关闭</span>'+toggle('telemetry',state.telemetry)+'</div><div class="row"><span>索引与日志</span><b>仅本机 · 演示</b></div>':state.settingsTab==='capabilities'?'<h2>平台与权限</h2><div class="row"><span>当前演示平台</span><b>'+state.system+'</b></div><div class="row"><span>限定目录读取</span><span class="pill good">可用 · 演示</span></div><div class="row"><span>快速卷扫描</span><span class="pill">未验证</span></div><div class="row"><span>云元数据边界</span><span class="pill">未验证范围跳过</span></div><div class="row"><span>读取权限</span><button onclick="permissionInfo()">查看系统入口</button></div><div class="row"><span>产品写入授权</span><button onclick="route(\'plans\')">审阅计划</button></div><div class="notice">读取权限、系统提权与产品授权分别判断。</div>':state.settingsTab==='policy'?'<h2>Agent 与有限授权</h2><div class="row"><span>有限预授权 · 默认关闭</span>'+toggle('preauth',state.preauth)+'</div><label class="form-label">精确根</label><input id="policyRoot" class="form-input" type="text" value="'+esc(state.policyRoot)+'"><div class="row"><span>模式</span><b>同卷隔离</b></div><div class="row"><span>单次上限</span><b>1 GiB · 1,000 项</b></div><div class="row"><span>累计上限（24 小时）</span><b>2 GiB · 2,000 项</b></div><div class="row"><span>有效期模板</span><b>30 天</b></div><div class="notice">完整命中精确根与模式才覆盖；实际配额需核心跨进程核算。</div><div class="row"><button onclick="agentHandoff()">体验 Agent 交接</button><button class="primary" onclick="state.policyRoot=$(\'policyRoot\').value.trim();toast(\'已保存演示策略\')">保存演示策略</button></div>':'<h2>演示场景</h2><label class="form-label">计划与执行场景</label><select aria-label="执行演示场景" onchange="state.scenario=this.value"><option value="normal" '+(state.scenario==='normal'?'selected':'')+'>正常执行</option><option value="changed" '+(state.scenario==='changed'?'selected':'')+'>首项身份变化 · 跳过</option><option value="interrupt" '+(state.scenario==='interrupt'?'selected':'')+'>中断 · 需要核对</option><option value="expired" '+(state.scenario==='expired'?'selected':'')+'>计划过期 · 重新生成</option></select><div class="notice">全部为浏览器内模拟，不读取或更改本机文件。</div><div class="row"><button onclick="showBenchmark()">查看 Mole 全局对齐</button><button onclick="route(\'activity\')">查看待核对示例</button></div>')+'</section></div>'}
function setSetting(key,value){state[key]=value;document.body.classList.toggle('reduce-motion',state.reduceMotion);if(key==='reduceMotion'){document.documentElement.style.setProperty('--motion',value?'none':'');document.querySelectorAll('.scan-ring').forEach(e=>e.style.animation=value?'none':'')}if(key==='preauth')toast(value?'已启用演示策略，超范围仍需人工审阅':'有限授权已关闭')}
function addProtection(){modal('添加保护路径','<label class="form-label" for="protectPath">演示路径</label><input type="text" id="protectPath" class="form-input" placeholder="D:/Projects">','<button class="primary" onclick="saveProtection()">添加</button>')}
function saveProtection(){const p=$('protectPath').value.trim();if(!p)return toast('请输入路径');state.protectedPaths.add(p);closeDialog();render()}
function permissionInfo(){modal('系统读取权限','<div class="detail-fact"><span>Windows</span><b>目录读取 / 系统授权</b></div><div class="detail-fact"><span>macOS</span><b>目录访问 / 完全磁盘访问</b></div><div class="notice">此按钮说明系统入口，预览不会打开真实权限设置。</div>')}
function showBenchmark(){modal('全局功能与视觉对齐','<div class="row"><span>清理 / AI</span><span>短摘要 → 分类 → 逐项展开</span></div><div class="row"><span>应用</span><span>图标行 + 原位关联内容 + 选择栏</span></div><div class="row"><span>分析</span><span>可下钻色块 + 路径栏 + 等价表格</span></div><div class="row"><span>维护</span><span>按问题选任务 + 影响 + 逐项报告</span></div><div class="row"><span>状态</span><span>指标与趋势 + 进程解释 + 快捷面板</span></div><div class="row"><span>本产品计划 / 恢复</span><span>固定范围、授权、核对与独立恢复</span></div><div class="notice">借鉴 Mole 官网公开界面与说明。扩展项为交互概念；未运行 Mole 桌面程序。</div>','<a href="https://mole.fit/zh/" target="_blank" style="align-self:center">Mole 官方功能 ↗</a>')}
function visibleSelectedIds(){if(state.page==='clean')return candidates.filter(c=>state.cleanGroup==='all'||c.group===state.cleanGroup).map(c=>c.id);if(state.page==='ai')return state.aiTab==='cache'?candidates.filter(c=>c.group==='ai'||c.id==='build').map(c=>c.id):[];if(state.page==='apps')return applications.filter(a=>(a.name+' '+a.source+' '+a.path).toLowerCase().includes(state.appSearch.toLowerCase())).flatMap(a=>a.items);return []}
function updateSelectionBar(){const items=selectedItems(),show=['clean','ai','apps'].includes(state.page)&&items.length>0;$('selectionBar').hidden=!show;if(show){const visible=new Set(visibleSelectedIds()),hidden=items.filter(i=>!visible.has(i.id)).length;$('selectionBar').innerHTML='<div class="selection-copy"><b>'+items.length+' 项缓存 · '+size(items.reduce((n,c)=>n+c.amount,0))+(hidden?' · '+hidden+' 项在当前筛选外':'')+'</b><small>用户数据与共享内容保留 · 选择不会修改文件</small></div><button onclick="state.selected.clear();render()">清除选择</button><button class="primary" onclick="createCachePlan()">审阅固定计划 →</button>'}}
function updateTaskChip(){const op=state.operation,scan=['running','stopping'].includes(state.scan);$('taskChip').hidden=!(op?.status==='running'&&(state.page!=='run'||state.viewOperationId!==op.planId)||scan&&state.page!=='clean');if(!$('taskChip').hidden){$('taskChip').textContent=op?.status==='running'?op.phase+' · '+op.index+'/'+op.items.length+' →':'只读扫描 · '+(state.scan==='stopping'?'停止中':'发现条目')+' →';$('taskChip').onclick=()=>op?.status==='running'?viewOperation(op.planId):route('clean')}}
let toastTimer;function toast(text){clearTimeout(toastTimer);$('toast').textContent=text;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,3300)}
function drawer(title,body,actions=''){$('drawerContent').innerHTML='<button class="close-button" onclick="closeDrawer()" aria-label="关闭详情">×</button><h2>'+title+'</h2>'+body+'<div class="drawer-actions">'+actions+'</div>';$('drawer').hidden=false;$('drawerBackdrop').hidden=false;$('drawer').querySelector('button')?.focus()}
function closeDrawer(){$('drawer').hidden=true;$('drawerBackdrop').hidden=true}
$('drawerBackdrop').onclick=closeDrawer;
function modal(title,body,actions=''){$('dialogContent').innerHTML='<button class="close-button" onclick="closeDialog()" aria-label="关闭弹窗">×</button><h2 id="dialogTitle">'+title+'</h2>'+body+'<div class="dialog-actions"><button onclick="closeDialog()">关闭</button>'+actions+'</div>';if(!$('dialog').open)$('dialog').showModal()}
function closeDialog(){$('dialog').close()}
function switchTheme(){document.body.classList.toggle('dark');try{localStorage.setItem('cleanmanager-suite-theme',document.body.classList.contains('dark')?'dark':'light')}catch{}}
function command(){modal('跳转功能','<label class="search" style="width:100%;margin-top:17px">⌕ <input id="commandSearch" placeholder="搜索功能" aria-label="搜索功能" oninput="filterCommands(this.value)"></label><div class="command-list" id="commandList"></div>');filterCommands('');setTimeout(()=>$('commandSearch').focus(),20)}
function filterCommands(q){$('commandList').innerHTML=Object.entries(pageNames).filter(([id,n])=>id!=='run'&&n.includes(q)).map(([id,n])=>'<button onclick="closeDialog();route(\''+id+'\')"><span>'+n+'</span><span>↵</span></button>').join('')}
$('commandButton').onclick=command;$('trayButton').onclick=showTray;$('themeButton').onclick=switchTheme;
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();command()}if(e.key==='Escape'){closeDrawer();$('contextMenu').hidden=true}});
try{document.body.classList.toggle('dark',localStorage.getItem('cleanmanager-suite-theme')==='dark')}catch{}
render();
